													b:miny() + b:sizey() / 2 - triagHeight / 2,
													triagWidth,
													triagHeight
												)
												
												local halfWayPoint = b:minx() + b:sizex() / 2
												local yellowBarWidth = xPos - b:minx() - triagWidth / 2
												
