					local penalty = const.EnvEffects.DarknessCTHPenalty
					if IsKindOf(attacker, "Unit") and attacker:HasNightVision() then
						local reductionPercent = CharacterEffectDefs.NightOps:ResolveValue("night_acc_penalty_reduction")
