													PlaceObj('XTemplateFunc', {
														'name', "UpdateValue(self, anyChanged)",
														'func', function (self, anyChanged)
															-- tudu
															if anyChanged then
																local hasChanges, changes, allData = self:HasValueChanged()
																if not hasChanges then
																	self:SetTransparency(155)
																else
																	self:SetTransparency(0)
																	local indices = {}
																	local lines = {}
																	for key, mod in sorted_pairs(allData) do
																		local body = _InternalTranslate(mod.display, mod)
																		if type(body) ~= "string" or not body:find("%w") then
																			goto jazz_skip_mod_line
																		end
																		if table.find(changes, key) then
																			lines[#lines + 1] = T{990002014, "<bullet_point> <text>", text = Untranslated(body)}
																			indices[lines[#lines]] = 999
																		else
																			lines[#lines + 1] = T{990002015, "<style WeaponModExtraModificationsTransparent><text></style>", text = Untranslated(body)}
																		end
																		::jazz_skip_mod_line::
																	end
																	
																	table.sort(lines, function(a, b)
																		local indexA = indices[a] or 0
																		local indexB = indices[b] or 0
																		return indexA < indexB
																	end)
																	
																	self:SetText(table.concat(lines, "\n"))
																end
															else
																self:SetTransparency(0)
															end
														end,
