										child.CreatePropValText = function(self, value, scale)			
											return Untranslated("-")
										end
								end
								if item.bind_to == "CritChance" and IsKindOf(context, "Firearm") then							
									child.CreatePropValText = function(self, value, scale)
										local unit 
										if context.owner then
											unit = g_Units[context.owner] or gv_UnitData[context.owner]
										else
											unit = GetInventoryUnit() or SelectedObj
										end
										if unit then
											value = unit:CalcCritChance(context)
										end
										return Untranslated( self:GetReverseValue() and FormatNumberProp(self:GetMaxProgress() - (value or 0), scale) or FormatNumberProp(value or 0, scale))
									end
								end	
								
								if item.bind_to == "Damage" and IsKindOf(context, "Firearm") then
									local action = CombatActions[context.AvailableAttacks[1]]
									action = action or CombatActions[context:GetBaseAttack()]							
									local shot_count = context:GetAutofireShots(action)
								
									if shot_count and shot_count > 0 then
										child.CreatePropValText = function(self, value, scale)
											local totalDmg, dmg = 0, 0
											local unit 
											if context.owner then
												unit = g_Units[context.owner] or gv_UnitData[context.owner]
											else
												unit = GetInventoryUnit() or SelectedObj
											end
											if not unit then
												local satellite = GetSatelliteDialog()
												local squad = satellite and satellite:HasMember("selected_squad") and satellite.selected_squad
												if squad and #(squad.units or empty_table) > 0 then
													unit = gv_UnitData[squad.units[1]]
												end
											end
											if unit then
												totalDmg, dmg = action:GetActionDamage(unit, false, { weapon = context })
												dmg = dmg or totalDmg
												if totalDmg == 0 then 
													totalDmg = context.Damage
													dmg = totalDmg 
													return Untranslated("<valign bottom -3><valign center>" .. dmg)
													end
											end
											return Untranslated((totalDmg / Max(1, dmg)) .. "<valign bottom -3><style InventoryRolloverPropSmall>x</style><valign center>" .. dmg)
										end
									end
								end
								if item.bind_to == "BaseRange" and IsKindOf(context, "Ordnance") then
										child.CreatePropValText = function(self, value, scale)			
											return Untranslated("-")
										end
								end
							end,
