												for _, wnd in ipairs(ctrl_right_area) do
													local wcontext = wnd:GetContext()
													local wnd_id = wnd:GetContext().session_id
													local is_grayouted = InventoryUIGrayOut(wcontext)
													wnd:SetTransparency(is_grayouted and 150 or 0)
